/**
 * Media storage (PM-2). Files (product images today) live outside PostgreSQL; the database keeps
 * only metadata and the random key. Two adapters share this interface:
 *
 *  - `filesystem`: a directory, in Docker a persistent named volume (DEV, local, tests);
 *  - `s3`: any S3-compatible object store (production), configured by environment variables.
 *
 * Keys are generated by the API only (`newImageKeys`) and checked against KEY_PATTERN by every
 * adapter, so no request value can ever reach a path or object name. Nothing here is public: the
 * admin API reads the bytes and serves them to authorised staff (private by default).
 */
import { randomBytes } from "node:crypto";

/** One stored object, as listed for the orphan clean-up (PM-3). */
export interface StoredObject {
  /** The object's key relative to the storage root; may be a stray name that is not a key. */
  key: string;
  size: number;
  lastModified: Date;
}

export interface MediaStorage {
  readonly kind: "filesystem" | "s3";
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  /** The bytes, or null when the object does not exist. */
  get(key: string): Promise<Buffer | null>;
  /** Removes the object; a missing object is not an error. */
  delete(key: string): Promise<void>;
  /**
   * Every object under `products/` (PM-3 orphan clean-up), including names that are not valid
   * keys (left-over temporary files). Read-only.
   */
  list(): AsyncIterable<StoredObject>;
  /** Removes a listed object that is not a valid key (a stray temporary file). */
  deleteStray(name: string): Promise<void>;
}

/** Temporary file names the filesystem adapter writes next to a key before renaming. */
export const STRAY_PATTERN =
  /^products\/[0-9a-f]{32}\/(?:original|display\.webp|thumb\.webp)\.[0-9a-f]{12}\.tmp$/;

/** Keys of product images (PM-2), listed and cleaned up by the orphan clean-up (PM-3). */
export const KEY_PATTERN = /^products\/[0-9a-f]{32}\/(?:original|display\.webp|thumb\.webp)$/;

/**
 * Keys of technical document revisions (PM-5). Kept under their own prefix, outside `products/`:
 * `list()` and the orphan clean-up never see them, so a revision file can never be taken for an
 * unreferenced image. Revisions are immutable and never deleted (DP-035, ADR-014).
 */
export const DOCUMENT_KEY_PATTERN = /^documents\/[0-9a-f]{32}\/document\.pdf$/;

export class MediaStorageError extends Error {
  override name = "MediaStorageError";
}

export function assertKey(key: string): string {
  if (!KEY_PATTERN.test(key) && !DOCUMENT_KEY_PATTERN.test(key)) {
    throw new MediaStorageError("invalid media key");
  }
  return key;
}

export interface ImageKeys {
  original: string;
  display: string;
  thumb: string;
}

/** Fresh random keys (128 bits) for one image and its derived variants. */
export function newImageKeys(): ImageKeys {
  const id = randomBytes(16).toString("hex");
  return {
    original: `products/${id}/original`,
    display: `products/${id}/display.webp`,
    thumb: `products/${id}/thumb.webp`,
  };
}

/** A fresh random key (128 bits) for one document revision (PM-5). */
export function newDocumentKey(): string {
  return `documents/${randomBytes(16).toString("hex")}/document.pdf`;
}

/** Storage that is not configured: every call fails with a storage error (503 to the client). */
export class DisabledStorage implements MediaStorage {
  readonly kind = "filesystem" as const;
  put(_key?: string, _data?: Buffer, _contentType?: string): Promise<void> {
    void [_key, _data, _contentType];
    return Promise.reject(new MediaStorageError("media storage is not configured"));
  }
  get(_key?: string): Promise<Buffer | null> {
    void _key;
    return Promise.reject(new MediaStorageError("media storage is not configured"));
  }
  delete(_key?: string): Promise<void> {
    void _key;
    return Promise.reject(new MediaStorageError("media storage is not configured"));
  }
  // eslint-disable-next-line require-yield
  async *list(): AsyncIterable<StoredObject> {
    throw new MediaStorageError("media storage is not configured");
  }
  deleteStray(_name?: string): Promise<void> {
    void _name;
    return Promise.reject(new MediaStorageError("media storage is not configured"));
  }
}
